css:
:scope { width: min(100%, 1360px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__img { overflow: hidden; border-radius: 1.75rem; margin: 5px; }
.gx__img a { position: absolute; inset: 0; display: block; z-index: 2; }
.gx__img a:focus-visible { outline: 3px solid var(--os-color-accent); outline-offset: -3px; border-radius: inherit; }
.gx__img .os-img { position: absolute; inset: 0; display: block; width: 100%; height: 100%; }
.gx__img picture { position: absolute; inset: 0; display: block; width: 100%; height: 100%; }
.gx__img img { position: absolute !important; inset: 0; display: block; width: 100% !important; height: 100% !important; max-width: none !important; object-fit: cover; object-position: 50% 0; transition: opacity .2s; }
.gx__img a:hover img { opacity: .9; }
.gx__i1 { grid-column: 1 / span 17; grid-row: 1 / span 17; font-family: var(--os-font-heading); font-size: 128.3px; font-weight: 400; line-height: 1.04; letter-spacing: -0.03em; color: var(--os-color-text); }
.gx__i2 { grid-column: 19 / span 6; grid-row: 1 / span 11; font-family: var(--os-font-label); font-size: 16px; font-weight: 400; line-height: 1.8; letter-spacing: -0.02em; color: var(--os-color-text); }
.gx__i3 { grid-column: 19 / span 6; grid-row: 13 / span 7; font-family: var(--os-font-label); font-size: 16px; font-weight: 400; line-height: 1.8; letter-spacing: -0.02em; color: var(--os-color-text); }
.gx__i4 { grid-column: 1 / span 17; grid-row: 22 / span 4; font-family: var(--os-font-label); font-size: 16px; font-weight: 400; line-height: 1.8; letter-spacing: -0.02em; color: var(--os-color-text); }
.gx__i5 { grid-column: 1 / span 8; grid-row: 32; aspect-ratio: 446 / 391; }
.gx__i6 { grid-column: 9 / span 8; grid-row: 32; aspect-ratio: 446 / 391; }
.gx__i7 { grid-column: 17 / span 8; grid-row: 32; aspect-ratio: 446 / 391; }
.gx__i8 { grid-column: 1 / span 8; grid-row: 33; aspect-ratio: 446 / 391; }
.gx__i9 { grid-column: 9 / span 8; grid-row: 33; aspect-ratio: 446 / 391; }
.gx__i10 { grid-column: 17 / span 8; grid-row: 33; aspect-ratio: 446 / 391; }
@media (max-width: 767px) {
  .gx { grid-template-columns: repeat(2, minmax(0, 1fr)); grid-auto-rows: auto; gap: 0.7rem; }
  .gx .gx__i { grid-column: 1 / -1; grid-row: auto; }
  .gx .gx__i1 { order: 0; font-size: clamp(2.5rem, 13vw, 3.25rem); line-height: 1.05; margin-bottom: 0.5rem; }
  .gx .gx__i4 { order: 1; font-size: 16px; margin-bottom: 1rem; }
  .gx .gx__i2 { order: 2; font-size: 16px; }
  .gx .gx__i3 { order: 3; font-size: 16px; margin-bottom: 0.5rem; }
  .gx .gx__img { grid-column: auto; grid-row: auto; margin: 0; width: 100%; aspect-ratio: 19 / 20; border-radius: 2.25rem; }
  .gx .gx__i8 { order: 10; }
  .gx .gx__i7 { order: 11; }
  .gx .gx__i10 { order: 12; }
  .gx .gx__i5 { order: 13; }
  .gx .gx__i6 { order: 14; }
  .gx .gx__i9 { order: 15; }
}
@media (prefers-reduced-motion: reduce) { .gx__img img { transition: none; } }
